library(tidyverse)
library(readxl)
library(stringr)
library(scales)

# Optional helpers (loaded only if installed)
has_pkg &lt;- function(pkg) {
  requireNamespace(pkg, quietly = TRUE)
}
use_pkg &lt;- function(pkg) {
  if (has_pkg(pkg)) {
    suppressPackageStartupMessages(library(pkg, character.only = TRUE))
    TRUE
  } else {
    FALSE
  }
}

# -----------------------------
# Helper: pick first path that exists
# -----------------------------
first_existing &lt;- function(paths) {
  hit &lt;- paths[file.exists(paths)]
  if (length(hit) == 0) NA_character_ else hit[1]
}

# -----------------------------
# Helper: identify columns that look like years (e.g., 2010, X2010)
# -----------------------------
get_year_cols &lt;- function(nm) {
  nm &lt;- as.character(nm)
  is_year &lt;- str_detect(nm, "^(X)?(19|20)\\d{2}$")
  nm[is_year]
}

# -----------------------------
# Helper: sanitize column names so dplyr/tibble never sees NA/blank names
# (Fixes: "Can't transform a data frame with `NA` or `\"\"` names.")
# -----------------------------
sanitize_names &lt;- function(x) {
  x &lt;- as.character(x)
  x &lt;- str_trim(x)

  # Replace NA / empty with stable placeholders
  bad &lt;- is.na(x) | x == ""
  if (any(bad)) {
    x[bad] &lt;- paste0("col_", which(bad))
  }

  # Make syntactic + unique
  x &lt;- make.names(x, unique = TRUE)

  # Light cleanup for readability
  x &lt;- str_replace_all(x, "\\.+", "_")
  x &lt;- str_replace_all(x, "^_|_$", "")
  x
}

# -----------------------------
# Helper: safely compute correlation matrix (returns NULL if insufficient numeric data)
# -----------------------------
safe_cor &lt;- function(df_numeric, method = "pearson") {
  if (is.null(df_numeric) || ncol(df_numeric) &lt; 2) return(NULL)

  df_num &lt;- df_numeric %&gt;%
    mutate(across(everything(), as.numeric)) %&gt;%
    select(where(~ !all(is.na(.x))))

  if (ncol(df_num) &lt; 2) return(NULL)

  tryCatch(
    stats::cor(df_num, use = "pairwise.complete.obs", method = method),
    error = function(e) NULL
  )
}
